    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students study a family of residue problems. For integers n with {n_min} \\le n \\le {n_max}, define A(n):=\\left\\lfloor\\dfrac{n!}{(n+1)(n+2)}\\right\\rfloor. Determine the complete set of values taken by the expression A(n) - \\left\\lfloor\\dfrac{A(n)}{{modulus}}\\right\\rfloor\\cdot {modulus} as n varies over all integers in the interval [{n_min}, {n_max}]. As your final answer, output the set (completely enumerating all elements) in the format: ### The final answer is: $\\boxed{\\{\\text{all elements}\\}}$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generalize the seed by keeping the core quotient but varying the modulus (a power of two)
# and asking for the full set of residues over a nontrivial interval of n.
# The generator will ensure the interval is large enough so that many distinct residues appear.
def compute_residues(n_min, n_max, modulus):
    # Compute the set of residues A(n) mod modulus for n in [n_min, n_max]
    residues = set()
    for n in range(n_min, n_max + 1):
        # Compute floor(n! / ((n+1)(n+2))) safely using Python big integers
        # To avoid huge intermediate multiplication by (n+1)(n+2), compute factorial then integer division.
        # Python's int handles big factorials.
        # For performance, we can compute factorial incrementally.
        # But given typical ranges (< 200), direct factorial is acceptable.
        # However we ensure n is not too large by choosing n_max <= 160.
        fact = 1
        for k in range(2, n + 1):
            fact *= k
        denom = (n + 1) * (n + 2)
        A = fact // denom  # floor division
        residues.add(A % modulus)
    return residues
# Try multiple random configurations to ensure richness of residue set.
for _ in range(20):
    alpha = rng.randint(30, 200)
    m_exp = rng.randint(5, 7)  # modulus exponent: 32..128
    modulus = 1 << m_exp
    n_min = rng.randint(18, 30)
    span = rng.randint(70, 120)
    n_max = n_min + span
    # Safety cap to avoid enormous factorials
    if n_max > 200:
        n_max = 200
    residues = compute_residues(n_min, n_max, modulus)
    # Heuristic difficulty check: we want at least 1/3 of all residues modulo modulus to appear.
    # This discourages trivial intervals.
    if len(residues) >= max(16, modulus // 3):
        return {
            'alpha': alpha,
            'n_min': n_min,
            'n_max': n_max,
            'modulus': modulus
        }
# Fallback deterministic assignment if random attempts fail
alpha = 100
modulus = 64
n_min = 20
n_max = 140
return {
    'alpha': alpha,
    'n_min': n_min,
    'n_max': n_max,
    'modulus': modulus
}

    def verifier(assign):
# Verify domain constraints and compute the exact answer set
# Return (True, answer_string) on success; otherwise (False, None)
try:
    alpha = int(assign.get('alpha'))
    n_min = int(assign.get('n_min'))
    n_max = int(assign.get('n_max'))
    modulus = int(assign.get('modulus'))
except Exception:
    # Missing or non-integer parameters
    return (False, None)
# Basic validations
if n_min < 1 or n_max < n_min:
    return (False, None)
# modulus must be a power of two at least 32
if modulus < 32:
    return (False, None)
# Check modulus is power of two
if modulus & (modulus - 1) != 0:
    return (False, None)
# Cap n_max to avoid pathological huge factorials
if n_max > 400:
    # too large; prevent heavy computation in verifier
    return (False, None)
# Compute residues
residues = set()
for n in range(n_min, n_max + 1):
    fact = 1
    for k in range(2, n + 1):
        fact *= k
    denom = (n + 1) * (n + 2)
    A = fact // denom
    residues.add(A % modulus)
# Format enumerated set in ascending order
sorted_vals = sorted(residues)
# Build LaTeX-style enumeration
elements_str = ", ".join(str(v) for v in sorted_vals)
answer = f"### The final answer is: \\boxed{{\\{{{elements_str}\\}}}}"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

